<template>
  <el-tooltip
    :content="text"
    :visible="visible"
    :enterable="false"
    :trigger-keys="[]"
    :show-after="0"
    :hide-after="immediate ? 0 : undefined"
    :transition="immediate ? 'none' : undefined"
    effect="light"
    placement="top"
  >
    <span
      v-bind="$attrs"
      ref="labelRef"
      :class="$slots.labelIcon ? [ns.b(), ns.is('with-icon')] : undefined"
      @mouseenter="!$slots.labelIcon && handleMouseEnter()"
      @mouseleave="handleMouseLeave"
    >
      <template v-if="$slots.labelIcon">
        <span
          ref="textRef"
          :class="ns.e('text')"
          @mouseenter="handleMouseEnter"
          @mouseleave="handleMouseLeave"
          >{{ text }}</span
        >
        <span :class="ns.e('icon')" @click.stop>
          <slot name="labelIcon" />
        </span>
      </template>
      <template v-else>{{ text }}</template>
    </span>
  </el-tooltip>
</template>

<script lang="ts" setup>
import { ref, watch } from 'vue'
import { useResizeObserver } from '@vueuse/core'
import { useNamespace } from '@element-plus/hooks'
import ElTooltip from './tooltip.vue'

defineOptions({
  name: 'ElFloatLabel',
  inheritAttrs: false,
})

const props = defineProps<{
  text?: string
  immediate?: boolean
}>()
const emit = defineEmits(['before-show'])
const ns = useNamespace('float-label')
const labelRef = ref<HTMLElement>()
const textRef = ref<HTMLElement>()
const visible = ref(false)
let hovering = false

const updateOverflow = () => {
  const label = textRef.value || labelRef.value
  const nextVisible = Boolean(
    hovering && label && label.scrollWidth > label.clientWidth
  )
  if (nextVisible && !visible.value) emit('before-show')
  visible.value = nextVisible
}

const handleMouseEnter = () => {
  hovering = true
  updateOverflow()
}

const handleMouseLeave = () => {
  hovering = false
  visible.value = false
}

useResizeObserver(labelRef, updateOverflow)
useResizeObserver(textRef, updateOverflow)
watch(() => props.text, updateOverflow, { flush: 'post' })

defineExpose({ hide: handleMouseLeave })
</script>
